// n8n Code node (Run Once for All Items)
// Parses emails that may contain MULTIPLE organizations:
// "Название: ...\nИНН: ...\nАдрес: ...\n\nНазвание: ...\nИНН ...\nАдрес: ..."

function stripPrefix(s = '', prefix = '') {
  s = String(s || '').trim();
  if (!prefix) return s;
  const re = new RegExp(`^${prefix}\\s*:\\s*`, 'i');
  return s.replace(re, '').trim();
}

function cleanHtml(s = '') {
  return String(s || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>|<\/div>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/\r/g, '')
    .trim();
}

function extractEmail(s = '') {
  s = String(s || '');
  const m = s.match(/<([^>]+)>/);
  if (m) return m[1].trim();
  const m2 = s.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return m2 ? m2[0].trim() : s.trim();
}

function normalizeSpaces(s = '') {
  return String(s)
    .replace(/\u00A0/g, ' ') // nbsp
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function toMoscowString(dateValue) {
  const d = new Date(dateValue);
  if (Number.isNaN(d.getTime())) return String(dateValue || '').trim();
  return d.toISOString();
}

function parseOrganizations(text) {
  const blocks = text
    .split(/\n(?=Название\s*:)/i)
    .map(b => b.trim())
    .filter(Boolean);

  const results = [];

  for (const block of blocks) {
    const nameMatch = block.match(/Название\s*:\s*(.+)/i);
    const org_name = nameMatch ? nameMatch[1].trim() : '';

    const innMatch = block.match(/ИНН\s*:?\s*(\d{10}|\d{12})/i);
    const inn = innMatch ? innMatch[1].trim() : '';

    // --- patched address parsing (cuts off signatures / next blocks) ---
    let org_address = '';
    const addrMatch = block.match(/Адрес\s*:\s*([\s\S]+)/i);

    if (addrMatch && addrMatch[1]) {
      org_address = addrMatch[1];

      // Обрезаем по "С уважением" и другим маркерам подписи
      org_address = org_address.split(/\n\s*(С уважением|--|Regards|Best regards)/i)[0];

      // Удаляем возможный следующий блок "Название:"
      org_address = org_address.split(/\n\s*Название\s*:/i)[0];

      // Нормализация
      org_address = org_address
        .replace(/\u00A0/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .replace(/,$/, '');
    }
    // --- end patch ---

    if (inn || org_name || org_address) {
      results.push({ org_name, inn, org_address });
    }
  }

  return results;
}

const inputItems = $input.all();
const output = [];

for (const item of inputItems) {
  const msg = item.json || {};
  const headers = msg.headers || {};

  const sender_email =
    msg.from?.value?.[0]?.address
      ? String(msg.from.value[0].address).trim()
      : extractEmail(stripPrefix(headers.from || msg.from?.text || '', 'From'));

  const subject =
    (msg.subject && String(msg.subject).trim()) ||
    stripPrefix(headers.subject || '', 'Subject') ||
    '';

  const messageDateRaw =
    (msg.date && String(msg.date).trim()) ||
    stripPrefix(headers.date || '', 'Date') ||
    '';

  const message_date = toMoscowString(messageDateRaw);

  const message_id = msg.id || msg.messageId || stripPrefix(headers['message-id'] || '', 'Message-Id') || '';
  const thread_id = msg.threadId || '';

  const bodyTextRaw =
    (msg.text && String(msg.text).trim()) ||
    cleanHtml(msg.html || msg.textAsHtml || '');

  const bodyText = normalizeSpaces(bodyTextRaw);

  const orgs = parseOrganizations(bodyText);

  const finalOrgs = orgs.length ? orgs : [{
    org_name: '',
    inn: (bodyText.match(/\b(\d{10}|\d{12})\b/) || [,''])[1],
    org_address: '',
  }];

  for (const org of finalOrgs) {
    output.push({
      json: {
        sender_email,
        inn: String(org.inn || '').replace(/\D/g, ''),
        org_name: org.org_name || '',
        org_address: org.org_address || '',
        message_date,
        subject,
        message_id,
        thread_id,
        body_short: bodyText.slice(0, 500),
        body_full: bodyText,
      }
    });
  }
}

return output;

function normalizeInn(value = '') {
  return String(value).replace(/\D+/g, '').trim();
}

// Берём ВСЕ элементы из Parse Email (их может быть несколько, если в письме
// перечислено несколько организаций)
const parsedItems = $items("Code - Parse Email").map(i => i.json);

// Строки из Google Sheets Read (это текущий input данной ноды)
const rows = $input.all().map(i => i.json || {});

// Сет ИНН из таблицы (быстрее и чище)
const innKeys = ['inn', 'ИНН', 'Inn', 'INN'];
function getRowInn(row) {
  for (const k of innKeys) {
    if (row[k] !== undefined && row[k] !== null) return normalizeInn(row[k]);
  }
  return '';
}

const innSet = new Set(
  rows.map(getRowInn).filter(Boolean)
);

// Возвращаем items по каждому parsed item
return parsedItems.map(p => {
  const inn = normalizeInn(p.inn || '');
  const exists = !!inn && innSet.has(inn);

  return {
    json: {
      ...p,
      inn,
      inn_exists: exists,
      rows_count: rows.length
    }
  };
});
